 -- Arbeitsrecht Berufsbildung > Betriebswirtschaftliche Grundlagen > Kostenrechnung > Einzelkosten
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind die Kosten für eine spezielle Projekt-Hardware Einzelkosten in einem IT-Betrieb?', 2, '[{"text": "Ja", "correct": true, "because": "Einzelkosten sind direkt einem Projekt zurechenbar"}, {"text": "Nein", "correct": false, "because": "Projekt-Hardware ist Einzelkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Zählen die Gehälter eines Fachinformatikers, der an einem bestimmten Projekt arbeitet, zu den Einzelkosten?', 2, '[{"text": "Ja", "correct": true, "because": "Projektbezogene Gehälter sind Einzelkosten"}, {"text": "Nein", "correct": false, "because": "Gehälter können Einzelkosten sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Einzelkosten in einem IT-Betrieb direkt einem Produkt oder Projekt zugeordnet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Einzelkosten sind per Definition direkt zurechenbar"}, {"text": "Nein", "correct": false, "because": "Direkte Zuordnung ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Einzelkosten wie Materialkosten für ein IT-Projekt variabel sein?', 2, '[{"text": "Ja", "correct": true, "because": "Materialkosten können je nach Projekt variieren"}, {"text": "Nein", "correct": false, "because": "Einzelkosten können variabel sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind die Stromkosten für einen Serverraum Einzelkosten?', 2, '[{"text": "Nein", "correct": true, "because": "Stromkosten sind Gemeinkosten, nicht direkt zurechenbar"}, {"text": "Ja", "correct": false, "because": "Stromkosten sind keine Einzelkosten"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kosten sind typische Einzelkosten in einem IT-Betrieb?', 2, '[{"text": "Kosten für spezifische Projekt-Hardware", "correct": true, "because": "Direkt einem Projekt zurechenbar"}, {"text": "Mietkosten für Büroräume", "correct": false, "because": "Gemeinkosten"}, {"text": "Abschreibungen auf Server", "correct": false, "because": "Gemeinkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie werden Einzelkosten in einem IT-Betrieb behandelt?', 3, '[{"text": "Direkt den Projekten zugeordnet", "correct": true, "because": "Einzelkosten sind direkt zurechenbar"}, {"text": "Über Zuschlagssätze verteilt", "correct": false, "because": "Das gilt für Gemeinkosten"}, {"text": "Nicht berücksichtigt", "correct": false, "because": "Einzelkosten sind relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart gehört nicht zu den Einzelkosten eines IT-Betriebs?', 3, '[{"text": "Stromkosten für Serverräume", "correct": true, "because": "Gemeinkosten, nicht direkt zurechenbar"}, {"text": "Kosten für Projektsoftware", "correct": false, "because": "Einzelkosten"}, {"text": "Gehälter für ein Projektteam", "correct": false, "because": "Einzelkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer trägt in einem IT-Betrieb die Einzelkosten?', 2, '[{"text": "Das jeweilige Projekt", "correct": true, "because": "Einzelkosten werden direkt zugeordnet"}, {"text": "Alle Projekte gemeinsam", "correct": false, "because": "Das gilt für Gemeinkosten"}, {"text": "Der Betrieb als Ganzes", "correct": false, "because": "Nicht direkt zurechenbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn Einzelkosten eines IT-Betriebs nicht korrekt zugeordnet werden?', 3, '[{"text": "Die Projektkalkulation wird verfälscht", "correct": true, "because": "Fehlerhafte Zuordnung beeinflusst die Kosten"}, {"text": "Die Kosten verschwinden", "correct": false, "because": "Kosten bleiben bestehen"}, {"text": "Keine Auswirkungen", "correct": false, "because": "Verfälschung hat Folgen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kosten sind Einzelkosten in einem IT-Betrieb?', 4, '[{"text": "Kosten für Projekt-Hardware", "correct": true, "because": "Direkt zurechenbar"}, {"text": "Gehälter für ein Projektteam", "correct": true, "because": "Projektbezogen"}, {"text": "Mietkosten für Büroräume", "correct": false, "because": "Gemeinkosten"}, {"text": "Kosten für spezifische Softwarelizenzen", "correct": true, "because": "Projektbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Einzelkosten in einem IT-Betrieb?', 3, '[{"text": "Direkte Zuordenbarkeit zu einem Projekt", "correct": true, "because": "Definition von Einzelkosten"}, {"text": "Können variabel sein", "correct": true, "because": "Einzelkosten variieren je nach Projekt"}, {"text": "Verteilung auf alle Projekte", "correct": false, "because": "Das sind Gemeinkosten"}, {"text": "Können fix sein", "correct": true, "because": "Einzelkosten können fix oder variabel sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten sind keine Einzelkosten in einem IT-Betrieb?', 3, '[{"text": "Stromkosten für Serverräume", "correct": true, "because": "Gemeinkosten"}, {"text": "Mietkosten für Büros", "correct": true, "because": "Gemeinkosten"}, {"text": "Kosten für Projekt-Hardware", "correct": false, "because": "Einzelkosten"}, {"text": "Abschreibungen auf Bürogeräte", "correct": true, "because": "Gemeinkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf Einzelkosten in einem IT-Betrieb zu?', 4, '[{"text": "Sie sind direkt zurechenbar", "correct": true, "because": "Definition von Einzelkosten"}, {"text": "Sie können Materialkosten umfassen", "correct": true, "because": "Material ist oft projektbezogen"}, {"text": "Sie werden über Zuschlagssätze verteilt", "correct": false, "because": "Das gilt für Gemeinkosten"}, {"text": "Sie können Lohnkosten umfassen", "correct": true, "because": "Projektbezogene Löhne sind Einzelkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet Einzelkosten von Gemeinkosten in einem IT-Betrieb?', 3, '[{"text": "Einzelkosten sind direkt zurechenbar", "correct": true, "because": "Definition von Einzelkosten"}, {"text": "Gemeinkosten werden verteilt", "correct": true, "because": "Gemeinkosten sind nicht direkt zurechenbar"}, {"text": "Einzelkosten sind immer fix", "correct": false, "because": "Einzelkosten können variabel sein"}, {"text": "Gemeinkosten sind projektbezogen", "correct": false, "because": "Gemeinkosten sind allgemein"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Einzelkosten sind direkt einem Projekt zurechenbar. b) Mietkosten für Serverräume sind Einzelkosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einzelkosten zurechenbar, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gehälter für ein Projektteam sind Einzelkosten. b) Einzelkosten können variabel sein.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Projektgehälter sind Einzelkosten, variabel möglich"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Stromkosten für Büros sind Einzelkosten. b) Kosten für Projektsoftware sind Einzelkosten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Projektsoftware Einzelkosten, a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Einzelkosten werden direkt zugeordnet. b) Gemeinkosten sind Einzelkosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einzelkosten zurechenbar, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Materialkosten für ein Projekt sind Einzelkosten. b) Einzelkosten müssen immer verteilt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Materialkosten Einzelkosten, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

